<?php
declare(strict_types=1);
namespace TripVora;
use DateTimeImmutable;
use Throwable;
final class TripService {
 public function quote(array $d,bool $save=false,int $userId=0):array {
 $destination=(int)($d['destination_id']??0);$people=(int)($d['people']??0);$start=(string)($d['start_date']??'');$end=(string)($d['end_date']??'');$a=DateTimeImmutable::createFromFormat('!Y-m-d',$start);$b=DateTimeImmutable::createFromFormat('!Y-m-d',$end);Http::must($a!==false&&$b!==false&&$a->format('Y-m-d')===$start&&$b->format('Y-m-d')===$end&&$b>=$a&&$a>=new DateTimeImmutable('today'),'Invalid travel dates');$days=(int)$a->diff($b)->days+1;Http::must($days<=60&&$people>=1&&$people<=20,'Trip duration or people out of range');Http::must((bool)DB::row('SELECT id FROM destinations WHERE id=:id',['id'=>$destination]),'Destination not found');$ids=array_values(array_unique(array_map('intval',$d['attraction_ids']??[])));Http::must(count($ids)<=30,'Too many attractions');$attractions=DB::rows('SELECT id,entry_price,duration_minutes FROM attractions WHERE destination_id=:id',['id'=>$destination]);$map=array_column($attractions,null,'id');$attractionsTotal=0;foreach($ids as $id){Http::must(isset($map[$id]),'Invalid attraction selection');$attractionsTotal+=(float)$map[$id]['entry_price']*$people;}
 $hotelId=(int)($d['hotel_id']??0);$vehicleId=(int)($d['vehicle_id']??0);$helmet=!empty($d['helmet']);$hotelTotal=0;$vehicleTotal=0;$nights=max(0,$days-1);
 if($hotelId){$hotel=DB::row('SELECT * FROM hotels WHERE id=:id AND destination_id=:destination AND active=1',['id'=>$hotelId,'destination'=>$destination]);Http::must((bool)$hotel,'Hotel not available');$occupied=DB::row("SELECT COUNT(*) c FROM trips WHERE hotel_id=:id AND status='booked' AND start_date<:checkout AND end_date>:checkin",['id'=>$hotelId,'checkout'=>$end,'checkin'=>$start]);Http::must((int)$occupied['c']<(int)$hotel['rooms_total'],'Hotel sold out for dates',409);$hotelTotal=(new PerNightCalculator())->total($nights,(float)$hotel['price_per_night']);}
 if($vehicleId){$vehicle=DB::row('SELECT * FROM vehicles WHERE id=:id AND destination_id=:destination AND active=1',['id'=>$vehicleId,'destination'=>$destination]);Http::must((bool)$vehicle,'Vehicle not available');$busy=DB::row("SELECT COUNT(*) c FROM trips WHERE vehicle_id=:id AND status='booked' AND start_date<=:finish AND end_date>=:begin",['id'=>$vehicleId,'finish'=>$end,'begin'=>$start]);Http::must((int)$busy['c']===0,'Vehicle already booked for these dates',409);$vehicleTotal=(new PerDayCalculator())->total($days,(float)$vehicle['price_per_day']);if($helmet&&$vehicle['vehicle_type']==='bike')$vehicleTotal+=50*$days;}
 $total=$attractionsTotal+$hotelTotal+$vehicleTotal;$quote=['ok'=>true,'days'=>$days,'nights'=>$nights,'attractions_total'=>$attractionsTotal,'hotel_total'=>$hotelTotal,'vehicle_total'=>$vehicleTotal,'total'=>$total];if(!$save)return $quote;
 $pdo=DB::conn();$pdo->beginTransaction();try{ // Serialize bookings to prevent overlapping concurrent reservations.
 DB::row('SELECT id FROM destinations WHERE id=:id FOR UPDATE',['id'=>$destination]);if($hotelId){$occupied=DB::row("SELECT COUNT(*) c FROM trips WHERE hotel_id=:id AND status='booked' AND start_date<:checkout AND end_date>:checkin",['id'=>$hotelId,'checkout'=>$end,'checkin'=>$start]);Http::must((int)$occupied['c']<(int)$hotel['rooms_total'],'Hotel sold out',409);}if($vehicleId){$busy=DB::row("SELECT COUNT(*) c FROM trips WHERE vehicle_id=:id AND status='booked' AND start_date<=:finish AND end_date>=:begin",['id'=>$vehicleId,'finish'=>$end,'begin'=>$start]);Http::must((int)$busy['c']===0,'Vehicle already booked',409);}
 DB::exec('INSERT INTO trips(user_id,destination_id,start_date,end_date,people,hotel_id,vehicle_id,helmet,attractions_total,hotel_total,vehicle_total,total) VALUES(:u,:d,:s,:e,:p,:h,:v,:helmet,:a,:ht,:vt,:total)',['u'=>$userId,'d'=>$destination,'s'=>$start,'e'=>$end,'p'=>$people,'h'=>$hotelId?:null,'v'=>$vehicleId?:null,'helmet'=>$helmet?1:0,'a'=>$attractionsTotal,'ht'=>$hotelTotal,'vt'=>$vehicleTotal,'total'=>$total]);$tripId=(int)$pdo->lastInsertId();foreach($ids as $id)DB::exec('INSERT INTO trip_attractions(trip_id,attraction_id) VALUES(:trip,:attraction)',['trip'=>$tripId,'attraction'=>$id]);$pdo->commit();$quote['trip_id']=$tripId;return $quote;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 }
 public function itinerary(int $destination,array $ids,int $days):array {$rows=DB::rows('SELECT id,name,duration_minutes FROM attractions WHERE destination_id=:id ORDER BY id',['id'=>$destination]);$chosen=array_values(array_filter($rows,fn($r)=>in_array((int)$r['id'],$ids,true)));$plan=array_fill(0,max(1,min(60,$days)),[]);$i=0;foreach($chosen as $a){$plan[$i%count($plan)][]=$a;$i++;}return $plan;}
}
